css:
.ecosystemsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2433;
    background: linear-gradient(160deg, #f5f1ea 0%, #ece4d6 100%);
    border-radius: 18px;
}

.ecosystemsim-container * {
    box-sizing: border-box;
}

.ecosystemsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #15233f 0%, #243a63 55%, #2f5a86 100%);
    color: #f7f2e7;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(21, 35, 63, 0.32);
}

.ecosystemsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.ecosystemsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e6b873;
    background: rgba(230, 184, 115, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.ecosystemsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7ddcb;
}

.ecosystemsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #344063;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.ecosystemsim-period-counter #currentDay,
.ecosystemsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #15233f;
}

.ecosystemsim-round-name {
    background: #dfd2bb;
    color: #5a3a18;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.ecosystemsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3d1e;
    background: #f4ddd0;
    padding: 4px 12px;
    border-radius: 999px;
}

.ecosystemsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.ecosystemsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3d9c6;
    box-shadow: 0 4px 14px rgba(21, 35, 63, 0.06);
    border-top: 4px solid #2f5a86;
}

.ecosystemsim-card-relevance { border-top-color: #2f5a86; }
.ecosystemsim-card-ecosystem { border-top-color: #1f7a5a; }
.ecosystemsim-card-sustain { border-top-color: #8a5fb0; }
.ecosystemsim-card-enrol { border-top-color: #c98a16; }

.ecosystemsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6d6453;
}

.ecosystemsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #15233f;
}

.ecosystemsim-card-relevance .ecosystemsim-value { color: #2f5a86; }
.ecosystemsim-card-ecosystem .ecosystemsim-value { color: #1f7a5a; }
.ecosystemsim-card-sustain .ecosystemsim-value { color: #8a5fb0; }
.ecosystemsim-card-enrol .ecosystemsim-value { color: #c98a16; }

.ecosystemsim-sublabel {
    font-size: 0.76rem;
    color: #847a66;
    line-height: 1.35;
}

.ecosystemsim-relevance-fail .ecosystemsim-value { color: #c0392b; }
.ecosystemsim-relevance-target .ecosystemsim-value { color: #1f7a5a; }

.ecosystemsim-budget-over { border-top-color: #c0392b; }
.ecosystemsim-budget-over .ecosystemsim-value { color: #c0392b; }

.ecosystemsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #15233f;
    color: #f4ecdd;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.ecosystemsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e6b873;
}

.ecosystemsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c98a16;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(21, 35, 63, 0.05);
}

.ecosystemsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.ecosystemsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #15233f;
    margin-bottom: 6px;
}

.ecosystemsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #38405a;
}

.ecosystemsim-briefing-text strong { color: #1f7a5a; }
.ecosystemsim-briefing-text em { color: #9a3d1e; font-style: italic; }

.ecosystemsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3d9c6;
    box-shadow: 0 4px 14px rgba(21, 35, 63, 0.06);
}

.ecosystemsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #15233f;
    border-bottom: 2px solid #efe7d7;
    padding-bottom: 8px;
}

.ecosystemsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3148;
    margin: 14px 0 6px;
}

.ecosystemsim-container select,
.ecosystemsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d3c6ab;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f1;
    color: #1f2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.ecosystemsim-container select:focus,
.ecosystemsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f5a86;
    box-shadow: 0 0 0 3px rgba(47, 90, 134, 0.15);
}

.ecosystemsim-container select option {
    background-color: #ffffff;
    color: #1f2433;
}

.ecosystemsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c98a16;
}

.ecosystemsim-range-readout,
.ecosystemsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f5a86;
    margin-top: 4px;
}

.ecosystemsim-range-readout span:last-child,
.ecosystemsim-alloc-readout span:nth-child(2) {
    color: #1f7a5a;
    font-weight: 800;
}

.ecosystemsim-hint {
    font-size: 0.8rem;
    color: #847a66;
    margin-top: 4px;
    line-height: 1.4;
}

.ecosystemsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.ecosystemsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f2e8;
    border: 1px solid #e6dcc8;
    border-radius: 9px;
    padding: 8px 12px;
}

.ecosystemsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2a3148;
}

.ecosystemsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.ecosystemsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.ecosystemsim-container .btn-primary {
    background: linear-gradient(135deg, #1f7a5a 0%, #2f5a86 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 122, 90, 0.28);
}

.ecosystemsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.ecosystemsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d3c6ab;
    color: #6d6453;
}

.ecosystemsim-coach {
    background: #15233f;
    color: #f1ece0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(21, 35, 63, 0.24);
}

.ecosystemsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6b873;
    margin-bottom: 8px;
}

.ecosystemsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.ecosystemsim-coach-body strong { color: #f2cf8a; }
.ecosystemsim-coach-body em { color: #f0b39a; font-style: italic; }

.ecosystemsim-history,
.ecosystemsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3d9c6;
    box-shadow: 0 4px 14px rgba(21, 35, 63, 0.06);
}

.ecosystemsim-history h3,
.ecosystemsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #15233f;
}

.ecosystemsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3148;
}

.ecosystemsim-container table#usfHistoryTable th {
    background: #f1ebdd;
    color: #15233f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3d9c6;
}

.ecosystemsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebe0;
}

.ecosystemsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.ecosystemsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .ecosystemsim-container {
        padding: 14px;
    }
    .ecosystemsim-header h1 {
        font-size: 1.7rem;
    }
    .ecosystemsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .ecosystemsim-value {
        font-size: 2rem;
    }
    .ecosystemsim-clock {
        margin-left: 0;
    }
    .ecosystemsim-period-counter {
        font-size: 0.88rem;
    }
    .ecosystemsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .ecosystemsim-alloc-row {
        flex-wrap: wrap;
    }
    .ecosystemsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .ecosystemsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (ecosystemsim) ---- */
.ecosystemsim-completion { padding: 8px 4px 4px; }
.ecosystemsim-cm-head { text-align: center; margin-bottom: 16px; }
.ecosystemsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f5a86; }
.ecosystemsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6f93b8; }
.ecosystemsim-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #15233f; }
.ecosystemsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.ecosystemsim-cm-yes { background: rgba(31,122,90,0.16); color: #1f7a5a; border: 1px solid rgba(31,122,90,0.5); }
.ecosystemsim-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.ecosystemsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.ecosystemsim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(47,90,134,0.08); border: 1px solid rgba(47,90,134,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.ecosystemsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f5a86; }
.ecosystemsim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.ecosystemsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #15233f; }
.ecosystemsim-cm-insights { margin: 0; padding-left: 20px; }
.ecosystemsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

