(function() {
    'use strict';

    class EcosystemAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Building the Ecosystem`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (concept §7).
            this.BUDGET_CAP = 4.5;            // EUR 4.5M ring-fenced seed
            this.RELEVANCE_TARGET = 70;       // board's "where to play" target
            // Meters start low and the per-round deltas are sized so the textbook-correct
            // playthrough lands near the top of the 0-100 band WITHOUT pinning any KPI at
            // 100. Saturation would absorb the penalty for a single wrong lever and let a
            // wrong choice tie the correct one — so headroom is preserved deliberately.
            this.START_RELEVANCE = 12;
            this.START_ECOSYSTEM = 10;
            this.START_SUSTAIN = 8;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    relevance: this.START_RELEVANCE,
                    ecosystem: this.START_ECOSYSTEM,
                    sustain: this.START_SUSTAIN,
                    enrol: 0,
                    budgetUsed: 0,
                    contingency: 0,
                    overBudget: false,
                    relevanceHistory: [this.START_RELEVANCE],
                    ecosystemHistory: [this.START_ECOSYSTEM],
                    sustainHistory: [this.START_SUSTAIN],
                    enrolHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately middling/neutral — a click-through
                // must NOT auto-win the textbook-correct strategy.
                state.decisions = {
                    response: `polish`,
                    segment: `graduates`,
                    assumption: 50,
                    partner: `academy`,
                    price: `match`,
                    content: 1.0,
                    tech: 1.0,
                    hiring: 1.0,
                    marketing: 1.0,
                    reskill: `buyonly`,
                    control: `cede`,
                    exclusivity: `grant`,
                    protect: 50,
                    scorecard: `enrolonly`,
                    finance: `spendall`,
                    stop: `addon`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const resp = document.getElementById(`responseInput`);
                const seg = document.getElementById(`segmentInput`);
                const asm = document.getElementById(`assumptionInput`);
                if (resp) decisions.response = resp.value;
                if (seg) decisions.segment = seg.value;
                if (asm) decisions.assumption = parseInt(asm.value, 10);
                if (!Number.isFinite(decisions.assumption) || decisions.assumption < 0 || decisions.assumption > 100) {
                    warn(`warn_assumption_range`); return false;
                }
            } else if (round === 2) {
                const part = document.getElementById(`partnerInput`);
                const price = document.getElementById(`priceInput`);
                if (part) decisions.partner = part.value;
                if (price) decisions.price = price.value;
                const content = document.getElementById(`contentInput`);
                const tech = document.getElementById(`techInput`);
                const hiring = document.getElementById(`hiringInput`);
                const marketing = document.getElementById(`marketingInput`);
                if (content) decisions.content = parseFloat(content.value);
                if (tech) decisions.tech = parseFloat(tech.value);
                if (hiring) decisions.hiring = parseFloat(hiring.value);
                if (marketing) decisions.marketing = parseFloat(marketing.value);
                const lines = [decisions.content, decisions.tech, decisions.hiring, decisions.marketing];
                if (lines.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.content + decisions.tech + decisions.hiring + decisions.marketing) * 100) / 100;
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_alloc_over`); return false;
                }
            } else if (round === 3) {
                const rsk = document.getElementById(`reskillInput`);
                const ctl = document.getElementById(`controlInput`);
                const exc = document.getElementById(`exclusivityInput`);
                const pr = document.getElementById(`protectInput`);
                if (rsk) decisions.reskill = rsk.value;
                if (ctl) decisions.control = ctl.value;
                if (exc) decisions.exclusivity = exc.value;
                if (pr) decisions.protect = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0 || decisions.protect > 100) {
                    warn(`warn_protect_range`); return false;
                }
            } else if (round === 4) {
                const sc = document.getElementById(`scorecardInput`);
                const fin = document.getElementById(`financeInput`);
                const stop = document.getElementById(`stopInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sc) decisions.scorecard = sc.value;
                if (fin) decisions.finance = fin.value;
                if (stop) decisions.stop = stop.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let relevanceDelta = 0, ecosystemDelta = 0, sustainDelta = 0, enrolDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Disruption response (Christensen): a separate engine for the disrupted
                // segment beats polishing the legacy core / waiting / a price war.
                switch (d.response) {
                    case `separate`: relevanceDelta += 14; ecosystemDelta += 5; sustainDelta += 3; coachKey = `coach_r1_separate`; break;
                    case `polish`:   relevanceDelta += 2;  sustainDelta -= 2; coachKey = `coach_r1_polish`; break;
                    case `ignore`:   relevanceDelta -= 6;  sustainDelta -= 4; coachKey = `coach_r1_ignore`; break;
                    case `acquire`:  relevanceDelta -= 4;  sustainDelta -= 6; coachKey = `coach_r1_acquire`; break;
                }

                // Segment focus: serve the fast-growing disrupted segment; refusing to
                // choose funds three half-programmes (Common Error 5).
                switch (d.segment) {
                    case `midcareer`:  relevanceDelta += 12; enrolDelta += 60; coachKey = (d.response === `separate`) ? `coach_r1_sharp` : coachKey; break;
                    case `graduates`:  relevanceDelta += 3;  enrolDelta += 25; break;
                    case `executives`: relevanceDelta += 5;  enrolDelta += 30; break;
                    case `everyone`:   relevanceDelta -= 8;  enrolDelta += 20; sustainDelta -= 4; coachKey = `coach_r1_everyone`; break;
                }

                // Rigour of the kill-assumption test: stress-testing the strategy lifts
                // relevance; refusing to test it leaves the strategy fragile.
                if (d.assumption >= 60) { relevanceDelta += 5; sustainDelta += 2; }
                else if (d.assumption <= 25) { relevanceDelta -= 5; coachKey = `coach_r1_noassumption`; }

                summaryKey = (d.response === `separate` && d.segment === `midcareer`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Partnership archetype: blended keeps brand + curriculum while co-creating;
                // white-label cedes brand + 30-40% revenue (Common Error 2); academy =
                // employer dependence; alone is slow + capital-hungry.
                switch (d.partner) {
                    case `blended`:    ecosystemDelta += 16; relevanceDelta += 5; sustainDelta += 5; enrolDelta += 35; coachKey = `coach_r2_blended`; break;
                    case `academy`:    ecosystemDelta += 8;  sustainDelta -= 3; enrolDelta += 55; coachKey = `coach_r2_academy`; break;
                    case `platform`:   ecosystemDelta += 6;  relevanceDelta += 3; sustainDelta -= 12; enrolDelta += 60; coachKey = `coach_r2_platform`; break;
                    case `consortium`: ecosystemDelta += 9;  sustainDelta += 2; enrolDelta += 20; coachKey = `coach_r2_consortium`; break;
                    case `alone`:      ecosystemDelta -= 4;  relevanceDelta += 2; sustainDelta += 2; enrolDelta += 15; coachKey = `coach_r2_alone`; break;
                }

                // Price against SkillForge: premium-but-credible captures the ecosystem
                // value; matching starts a price war you lose; full legacy price ignores
                // the disruptor and prices out the segment.
                switch (d.price) {
                    case `premium`: relevanceDelta += 9;  sustainDelta += 5; enrolDelta += 20; break;
                    case `match`:   relevanceDelta += 2;  sustainDelta -= 8; enrolDelta += 30; coachKey = `coach_r2_pricematch`; break;
                    case `luxury`:  relevanceDelta -= 8;  enrolDelta -= 25; coachKey = `coach_r2_priceluxury`; break;
                }

                // Allocation: spend the lines but KEEP a contingency. Spending the whole
                // 4.5 leaves no Year-2 bridge (Common Error 3); under-funding starves the
                // launch.
                const committed = Math.round((d.content + d.tech + d.hiring + d.marketing) * 100) / 100;
                spend = committed;
                const contingency = Math.round((this.BUDGET_CAP - committed) * 100) / 100;
                if (committed >= 4.45) { sustainDelta -= 14; enrolDelta += 10; coachKey = `coach_r2_spendall`; }
                else if (contingency >= 0.3 && contingency <= 1.2) { sustainDelta += 8; relevanceDelta += 3; }
                else if (contingency > 1.2) { enrolDelta -= 20; relevanceDelta -= 4; coachKey = `coach_r2_underfund`; }

                // Balance across the four lines: starving content reskilling or tech
                // weakens delivery; lopsided marketing buys noise, not capability.
                if (d.content >= 1.0 && d.tech >= 0.8) { relevanceDelta += 3; }
                if (d.content < 0.5) { relevanceDelta -= 6; coachKey = `coach_r2_thincontent`; }

                summaryKey = (d.partner === `blended` && d.price === `premium` && committed < 4.45) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Reskilling (build vs buy): reskill the willing + hire for true gaps beats
                // buy-only, mandate, or ignoring people (Common Error 4).
                switch (d.reskill) {
                    case `buildincentive`: ecosystemDelta += 8;  sustainDelta += 12; relevanceDelta += 6; coachKey = `coach_r3_build`; break;
                    case `buyonly`:        ecosystemDelta += 2;  sustainDelta -= 4; relevanceDelta += 2; coachKey = `coach_r3_buyonly`; break;
                    case `mandate`:        sustainDelta -= 10; relevanceDelta -= 4; coachKey = `coach_r3_mandate`; break;
                    case `ignore`:         sustainDelta -= 14; relevanceDelta -= 8; coachKey = `coach_r3_ignore`; break;
                }

                // EdTech control demand: co-govern protects the core while scaling; ceding
                // hands away brand + 38% revenue; holding hard slows scale.
                switch (d.control) {
                    case `shared`: ecosystemDelta += 12; sustainDelta += 5; coachKey = (d.reskill === `buildincentive`) ? `coach_r3_shared` : coachKey; break;
                    case `hold`:   ecosystemDelta += 4;  sustainDelta += 4; enrolDelta -= 10; break;
                    case `cede`:   ecosystemDelta += 6;  sustainDelta -= 16; enrolDelta += 25; coachKey = `coach_r3_cede`; break;
                }

                // Employer exclusivity: declining keeps the ecosystem open; granting trades
                // breadth for one captive customer.
                if (d.exclusivity === `decline`) { ecosystemDelta += 9; sustainDelta += 4; }
                else { ecosystemDelta -= 10; enrolDelta += 30; sustainDelta -= 4; coachKey = `coach_r3_exclusivity`; }

                // Protect the paying core without letting it veto the future.
                if (d.protect >= 45 && d.protect <= 75) { relevanceDelta += 6; sustainDelta += 3; }
                else if (d.protect > 90) { relevanceDelta -= 6; coachKey = `coach_r3_overprotect`; }
                else if (d.protect <= 20) { sustainDelta -= 8; coachKey = `coach_r3_noprotect`; }

                summaryKey = (d.reskill === `buildincentive` && d.control === `shared` && d.exclusivity === `decline`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Innovation scorecard: leading + lagging beats vanity headcount or a
                // launch-week press splash (Common Error 5 of measurement).
                switch (d.scorecard) {
                    case `leadlag`:   ecosystemDelta += 6; sustainDelta += 8; relevanceDelta += 5; coachKey = `coach_r4_leadlag`; break;
                    case `enrolonly`: sustainDelta -= 4; coachKey = `coach_r4_enrolonly`; break;
                    case `launchpr`:  sustainDelta -= 10; relevanceDelta -= 4; coachKey = `coach_r4_launchpr`; break;
                }

                // Financing beyond the seed: bridge break-even + reinvest is the 3-year
                // path off 62% dependence; spend-all shows a launch not a business; a
                // subsidy assumption is wishful.
                switch (d.finance) {
                    case `reinvest`: sustainDelta += 13; relevanceDelta += 3; coachKey = (d.scorecard === `leadlag`) ? `coach_r4_reinvest` : coachKey; break;
                    case `spendall`: sustainDelta -= 14; enrolDelta += 10; coachKey = `coach_r4_spendall`; break;
                    case `subsidy`:  sustainDelta -= 10; coachKey = `coach_r4_subsidy`; break;
                }

                // What the school stops doing: sunsetting sub-scale masters funds the
                // future; stopping nothing spreads thin; cutting exec-ed kills the cash
                // that funds the transition.
                switch (d.stop) {
                    case `sunset`:  sustainDelta += 9; relevanceDelta += 5; ecosystemDelta += 3; break;
                    case `addon`:   sustainDelta -= 8; relevanceDelta -= 4; coachKey = `coach_r4_addon`; break;
                    case `cutexec`: sustainDelta -= 14; enrolDelta -= 10; coachKey = `coach_r4_cutexec`; break;
                }

                // Conviction: defend a separate, durable ecosystem over a fast paper win.
                relevanceDelta += Math.round((d.conviction - 60) / 10);
                if (d.conviction >= 75) { sustainDelta += 3; }

                summaryKey = (d.scorecard === `leadlag` && d.finance === `reinvest` && d.stop === `sunset`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (R2 commits the seed; contingency = cap - committed).
            if (round === 2) {
                ds.budgetUsed = Math.round((d.content + d.tech + d.hiring + d.marketing) * 100) / 100;
                ds.contingency = Math.round((this.BUDGET_CAP - ds.budgetUsed) * 100) / 100;
                ds.overBudget = ds.budgetUsed > this.BUDGET_CAP + 0.001;
            }

            // Apply deltas with floors/ceilings (meters start low, keep headroom).
            ds.relevance = Math.max(0, Math.min(100, ds.relevance + relevanceDelta));
            ds.ecosystem = Math.max(0, Math.min(100, ds.ecosystem + ecosystemDelta));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustainDelta));
            ds.enrol = Math.max(0, Math.round(ds.enrol + enrolDelta));

            ds.relevanceHistory.push(Math.round(ds.relevance));
            ds.ecosystemHistory.push(Math.round(ds.ecosystem));
            ds.sustainHistory.push(Math.round(ds.sustain));
            ds.enrolHistory.push(ds.enrol);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                relevance: Math.round(ds.relevance),
                relevanceDelta: Math.round(relevanceDelta),
                ecosystem: Math.round(ds.ecosystem),
                ecosystemDelta: Math.round(ecosystemDelta),
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustainDelta),
                enrol: ds.enrol,
                enrolDelta: Math.round(enrolDelta),
                budgetUsed: ds.budgetUsed,
                contingency: ds.contingency,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            const self = this;
            const lang = () => (window.mySimulation && window.mySimulation.language) || `en`;

            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`relevanceDisplay`, `domainState.relevance`, (v) => {
                const card = document.querySelector(`.ecosystemsim-card-relevance`);
                if (card) {
                    card.classList.toggle(`ecosystemsim-relevance-target`, Number(v) >= this.RELEVANCE_TARGET);
                    card.classList.toggle(`ecosystemsim-relevance-fail`, Number(v) < 35);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`ecosystemDisplay`, `domainState.ecosystem`, (v) => Math.round(Number(v)));
            uiManager.bind(`sustainDisplay`, `domainState.sustain`, (v) => Math.round(Number(v)));
            uiManager.bind(`enrolDisplay`, `domainState.enrol`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => self._money(Number(v), lang()) + ` / ` + self._money(this.BUDGET_CAP, lang()));

            // Assumption-rigour slider readout.
            const asm = document.getElementById(`assumptionInput`);
            const asmReadout = document.getElementById(`assumptionReadout`);
            if (asm && asmReadout) {
                asmReadout.textContent = asm.value;
                asm.addEventListener(`input`, function() { asmReadout.textContent = asm.value; });
            }

            // Protect-the-core slider readout.
            const pr = document.getElementById(`protectInput`);
            const prReadout = document.getElementById(`protectReadout`);
            if (pr && prReadout) {
                prReadout.textContent = pr.value;
                pr.addEventListener(`input`, function() { prReadout.textContent = pr.value; });
            }

            // Allocation live total + contingency.
            const allocIds = [`contentInput`, `techInput`, `hiringInput`, `marketingInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const contingencyReadout = document.getElementById(`contingencyReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                const left = Math.round((self.BUDGET_CAP - total) * 100) / 100;
                if (allocReadout) allocReadout.textContent = self._money(total, lang());
                if (contingencyReadout) contingencyReadout.textContent = self._money(left, lang());
                const bar = document.querySelector(`.ecosystemsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP + 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        // Locale-aware EUR formatter in millions: EN "€2.4M" (symbol before, dot decimal);
        // ES "2,4 M€" (symbol after, comma decimal).
        _money(valueM, lang) {
            const v = Math.round(Number(valueM) * 10) / 10;
            if (lang === `es`) {
                return v.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + v.toFixed(1) + `M`;
        }

