        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.relevanceHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                ecosystemChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.relevanceHistory },
                        { data: ds.ecosystemHistory },
                        { data: ds.sustainHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const relevance = Math.round(ds.relevance);
            const ecosystem = Math.round(ds.ecosystem);
            const sustain = Math.round(ds.sustain);
            const enrol = Math.round(ds.enrol);
            return Math.max(0, Math.min(100, Math.round(relevance * 0.34 + ecosystem * 0.28 + sustain * 0.28 + Math.min(100, enrol / 2) * 0.10)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const relevance = Math.round(ds.relevance);
            const ecosystem = Math.round(ds.ecosystem);
            const sustain = Math.round(ds.sustain);
            const enrol = Math.round(ds.enrol);

            const hitTarget = relevance >= this.RELEVANCE_TARGET;
            const durable = ecosystem >= 55 && sustain >= 55;
            const composite = this._composite(ds);

            let performance = window.mySimulation.t(`grade_outpositioned`);
            if (hitTarget && durable && composite >= 74) performance = window.mySimulation.t(`grade_built`);
            else if (hitTarget && durable) performance = window.mySimulation.t(`grade_durable`);
            else if (hitTarget && sustain < 45) performance = window.mySimulation.t(`grade_noyear2`);
            else if (hitTarget) performance = window.mySimulation.t(`grade_fragile`);
            else if (relevance > this.START_RELEVANCE + 20) performance = window.mySimulation.t(`grade_closing`);

            const insights = [];
            if (hitTarget && durable) insights.push(window.mySimulation.t(`insight_built`));
            else if (hitTarget && sustain < 45) insights.push(window.mySimulation.t(`insight_noyear2`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_fragile`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (sustain < 45) insights.push(window.mySimulation.t(`insight_lowsustain`));
            if (ecosystem < 45) insights.push(window.mySimulation.t(`insight_lowecosystem`));
            if (enrol < 40) insights.push(window.mySimulation.t(`insight_lowenrol`));
            if (hitTarget && durable && composite >= 80) insights.push(window.mySimulation.t(`insight_exemplary`));

            return {
                relevance: relevance,
                ecosystem: ecosystem,
                sustain: sustain,
                enrol: enrol,
                hitTarget: hitTarget,
                durable: durable,
                met: (hitTarget && durable),
                overBudget: !!ds.overBudget,
                noYear2: (hitTarget && sustain < 45),
                outPositioned: !hitTarget,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="ecosystemsim-cm-badge ecosystemsim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="ecosystemsim-cm-badge ecosystemsim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.overBudget) failBadge += ` <span class="ecosystemsim-cm-badge ecosystemsim-cm-no">` + T(`cm_overbudget`) + `</span>`;
            if (s.noYear2) failBadge += ` <span class="ecosystemsim-cm-badge ecosystemsim-cm-no">` + T(`cm_noyear2`) + `</span>`;
            if (s.outPositioned) failBadge += ` <span class="ecosystemsim-cm-badge ecosystemsim-cm-no">` + T(`cm_outpositioned`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="ecosystemsim-cm-metric"><span class="ecosystemsim-cm-mv">` + Math.round(s.relevance || 0) + `</span><span class="ecosystemsim-cm-ml">` + T(`cm_m_relevance`) + `</span></div>`
                + `<div class="ecosystemsim-cm-metric"><span class="ecosystemsim-cm-mv">` + Math.round(s.ecosystem || 0) + `</span><span class="ecosystemsim-cm-ml">` + T(`cm_m_ecosystem`) + `</span></div>`
                + `<div class="ecosystemsim-cm-metric"><span class="ecosystemsim-cm-mv">` + Math.round(s.sustain || 0) + `</span><span class="ecosystemsim-cm-ml">` + T(`cm_m_sustain`) + `</span></div>`
                + `<div class="ecosystemsim-cm-metric"><span class="ecosystemsim-cm-mv">` + Math.round(s.enrol || 0) + `</span><span class="ecosystemsim-cm-ml">` + T(`cm_m_enrol`) + `</span></div>`;
            return ``
                + `<div class="ecosystemsim-completion">`
                +   `<div class="ecosystemsim-cm-head">`
                +     `<div class="ecosystemsim-cm-score">` + score + `<span class="ecosystemsim-cm-score-max">/100</span></div>`
                +     `<div class="ecosystemsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="ecosystemsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="ecosystemsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="ecosystemsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.sustain < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sustain`);
            if (ds.ecosystem < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_ecosystem`);
            if (state.currentPeriod >= 3 && ds.relevance < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.relevance >= this.RELEVANCE_TARGET && ds.ecosystem >= 55 && ds.sustain >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

